'use strict';

function runStages(initialValue, stages) {
  if (!Array.isArray(stages)) {
    throw new TypeError('stages must be an array');
  }
  for (const stage of stages) {
    if (typeof stage !== 'function') {
      throw new TypeError('every stage must be a function');
    }
  }

  return (async () => {
    let value = initialValue;
    for (const stage of stages) {
      value = await Reflect.apply(stage, undefined, [value]);
    }
    return value;
  })();
}

module.exports = { runStages };
